package com.yuegang.zhihui.knowledge.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.knowledge.api.*;import java.sql.*;import java.time.ZoneOffset;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;public final class KnowledgeLifecycleService{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public KnowledgeLifecycleService(DataSource d){jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public List<KnowledgeDocumentView>list(String status,String category,boolean publicOnly,int limit){StringBuilder q=new StringBuilder("SELECT id,title,category,file_name,media_type,size_bytes,sha256,status,version,updated_at FROM knowledge_document WHERE 1=1");List<Object>a=new ArrayList<>();if(publicOnly){q.append(" AND status='PUBLISHED' AND (expires_at IS NULL OR expires_at>NOW(6))");}else if(status!=null&&!status.isBlank()){q.append(" AND status=?");a.add(status);}if(category!=null&&!category.isBlank()){q.append(" AND category=?");a.add(category);}q.append(" ORDER BY updated_at DESC LIMIT ?");a.add(Math.max(1,Math.min(limit,100)));return jdbc.query(q.toString(),(r,n)->map(r),a.toArray());}public KnowledgeDocumentView offline(long operator,String document,long version,String reason){return tx.execute(s->{long id=id(document);if(jdbc.update("UPDATE knowledge_document SET status='OFFLINE',version=version+1 WHERE id=? AND version=? AND status='PUBLISHED'",id,version)!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);jdbc.update("INSERT INTO knowledge_status_history(id,document_id,from_status,to_status,operator_id,reason) VALUES(?,?, 'PUBLISHED','OFFLINE',?,?)",next(),id,operator,reason);jdbc.update("INSERT INTO knowledge_index_job(id,document_id,index_version,job_type,status) VALUES(?,?,?,'DELETE','PENDING')",next(),id,"knowledge-v"+System.currentTimeMillis());return get(id);});}private KnowledgeDocumentView get(long id){return jdbc.query("SELECT id,title,category,file_name,media_type,size_bytes,sha256,status,version,updated_at FROM knowledge_document WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return map(r);},id);}private static KnowledgeDocumentView map(ResultSet r)throws SQLException{return new KnowledgeDocumentView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getLong(6),r.getString(7),KnowledgeStatus.valueOf(r.getString(8)),r.getLong(9),r.getTimestamp(10).toLocalDateTime().atOffset(ZoneOffset.UTC));}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private static long id(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
